'use strict';
// The original tool creates an extract task, then continues that same task with
// one task-wide billing base. billing_base_wan is the legacy API key; its value
// is supplied in yuan, exactly as the original Vue screen does.
const pwBase={workbench,configPanel,handleAction,modalContent,closeModal,twMountPreview,configurationFragment,makeResult,prepaidResults,exportRows,doExport,reportText,trDownloadPage,tcOutput,pgLibrary,seedConfig};
const PW_TYPES=['supervision_engineering','design','agency_management','cost_consulting','survey_mapping','bidding_agency'];
const pwView={panel:'materials',task:null,tab:'agreement',query:'',page:1,size:20};
let pwSourceReturn=null;
function pwActive(){return state.view==='tool'&&state.toolId==='prepaid';}
function pwPreparing(){return pwActive()&&!currentTask();}
function pwConfig(){return currentTask()?.config||ws().config;}
function pwDefaultPrompt(key,c){const type=c.feeType||EXPENSE_TYPES[0];return{name:type+' · '+(key==='agreement'?'提取计费约定':'费用计算'),content:key==='agreement'?'从合同原文提取'+type+'的计费依据、基数、费率或固定总价、调整条件与来源；未提取到的内容如实标注。':'依据已提取的'+type+'合同约定和用户确认的基数计算费用，列出公式、单位、结果及来源，不套用合同之外的收费标准。'};}
pgLibrary=function(id,key){const items=pwBase.pgLibrary(id,key);if(id!=='prepaid')return items;const c=currentTask()?.toolId==='prepaid'?currentTask().config:state.work.prepaid?.config||PG_ROOT_DEFAULTS.prepaid,def=pwDefaultPrompt(key,c);return items.map(item=>item.value==='system'?{...item,name:def.name,content:def.content}:item);};
seedConfig=function(id,c){pwBase.seedConfig(id,c);if(id!=='prepaid'||c!==state.work.prepaid?.config||state.work.prepaid.taskId)return c;for(const key of ['agreement','calculation']){const s=c.stages[key],old=PG_ROOT_DEFAULTS.prepaid.stages[key],def=pwDefaultPrompt(key,c);if(s&&!s.customized&&s.origin==='system'&&(!s.pgChoice||s.pgChoice==='system')&&s.template===old.template&&s.content===old.content){s.template=def.name;s.content=def.content;s.pgChoice='system';s.scope='public';s.category='system';}}return c;};
function pwMoney(n){return Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function pwParseBase(value){const text=String(value??'').trim().replaceAll(',','').replaceAll('，','');if(!/^(?:\d+(?:\.\d{0,2})?|\.\d{1,2})$/.test(text))return NaN;const n=Number(text);return Number.isFinite(n)&&n>0&&n<=1e13?n:NaN;}
function pwDisposal(row){let value=row.disposal_result??row.DISPOSAL_RESULT??row.disposal;try{if(typeof value==='string')value=JSON.parse(value);}catch{return{text_1:value};}return value&&typeof value==='object'?value:{};}
function pwRawReport(d){if(d.phase!=='calculate')return '';if(String(d.calculation_result_text??'').trim())return String(d.calculation_result_text);for(const key of ['output','text_1','text_2']){const v=d.raw_dify?.[key];if(typeof v==='string'&&v.trim())return v;if(Array.isArray(v)&&v.length)return v.map(x=>String(x??'')).join('\n');}return '';}
function pwScope(t){return new Set([...(t.ids||[]),...(t.config?.merge?Object.values(t.attachments||{}).flat():[])]);}
function pwReadable(row,download=false){return row.refs.length>0&&row.scopeValid&&row.refs.every(id=>{const d=file(id);return d&&!d.deleted&&auditFileAccess(d).read&&(!download||auditFileAccess(d).download);});}
function pwRows(t){const allowed=pwScope(t),head=(t.result||[]).find(r=>r.doc||r.file_uuid),first=head?.doc||head?.file_uuid||(t.ids||[])[0],groups=new Map();(t.result||[]).forEach((raw,index)=>{const d=pwDisposal(raw),doc=raw.doc||raw.file_uuid||raw.FILE_UUID||(t.ids?.length===1?t.ids[0]:null),refs=[...new Set([doc,...(Array.isArray(raw.refs)?raw.refs:[])].filter(Boolean))],billing=raw.billing_snapshot||t.billingByDoc?.[doc]||(doc===first?t.billing:null),clause=String(d.phase==='calculate'?'':d.text_1||d.billing_agreement_text||raw.billing_agreement_text||raw.excerpt||billing?.clause||''),report=pwRawReport(d),key=doc||'missing-'+index;let row=groups.get(key);if(!row){row={index,doc,refs,scopeValid:refs.every(id=>allowed.has(id)),billing,clause,raw,raws:[raw],nativeReport:report,calculation:t.prepaidCalculations?.find(r=>r.doc===doc)||null};groups.set(key,row);}else{row.refs=[...new Set([...row.refs,...refs])];row.scopeValid=row.scopeValid&&refs.every(id=>allowed.has(id));row.raws.push(raw);if(clause&&!row.clause.includes(clause))row.clause+=(row.clause?'\n\n':'')+clause;if(report)row.nativeReport+=(row.nativeReport?'\n\n':'')+report;row.billing??=billing;}});return[...groups.values()].filter(r=>r.clause||r.nativeReport);}
function pwNativeReport(t,download=false){const allRows=pwRows(t),rows=allRows.filter(r=>pwReadable(r,download)),text=rows.map(r=>r.nativeReport).filter(Boolean).join('\n\n---\n\n');if(text)return text;const all=allRows.every(r=>pwReadable(r,download))&&(t.ids||[]).every(id=>{const d=file(id);return d&&!d.deleted&&auditFileAccess(d).read&&(!download||auditFileAccess(d).download);});return all?String(t.calculateAgentOutput||t.calculation_result_text||''):'';}
function pwFormula(b,base){if(!b)return '计费条件未完整返回';if(Number.isFinite(Number(b.rate))&&Number(b.rate)>0)return pwMoney(base)+' 元 × '+Number((Number(b.rate)*100).toFixed(8))+'%';if(b.fixed!=null&&Number.isFinite(Number(b.fixed))&&Number(b.fixed)>=0)return '合同固定总价 '+pwMoney(b.fixed)+' 元';return '计费条件未完整返回';}
function pwCalculation(t,row){if(row.calculation)return row.calculation;if(t.fee!=null&&pwRows(t).length===1)return{doc:row.doc,fee:t.fee,formula:pwFormula(row.billing,t.base),status:'calculated'};return null;}
function pwMaterials(){const root=document.createElement('div');root.innerHTML=twMaterials();const h=root.querySelector('.tw-panel-head h2');if(h){h.innerHTML='<span class="tw-step">Step 1</span> 计费合同';h.parentElement.insertAdjacentHTML('beforeend',B('添加资料','add-tool-materials','soft sm','aria-label="添加计费合同"'));}const intro=root.querySelector('.tw-intro');if(intro)intro.textContent='添加需要核算费用的合同，可关联补充协议。下方为本次已选资料。';return root.innerHTML;}
function pwPanel(){const c=pwConfig(),locked=!!currentTask();return '<aside class="config ew-config tw-config pg-config pw-config"><div class="pw-panel-head"><h2><span class="tw-step">'+(locked?'执行配置':'Step 2')+'</span> 设置费用核算</h2></div><div class="pw-config-scroll"><label class="pw-type">费用类型<select data-config="feeType" aria-label="费用类型" '+(locked?'disabled':'')+'>'+EXPENSE_TYPES.map(n=>'<option '+(n===c.feeType?'selected':'')+'>'+E(n)+'</option>').join('')+'</select></label><ol class="pw-flow"><li><b>提取计费约定</b><span>从合同整理计费依据和条件</span></li><li><b>确认基数并计算</b><span>填写金额，继续同一任务</span></li><li><b>核对费用报告</b><span>保留计算过程和合同来源</span></li></ol><div class="pw-prompts">'+pgStageCard('prepaid','agreement',c,locked)+pgStageCard('prepaid','calculation',c,locked)+'</div>'+'</div></aside>';}
configPanel=function(){return pwActive()?pwPanel():pwBase.configPanel();};
workbench=function(){if(!pwPreparing())return pwBase.workbench();const w=ws();if(!w.ids.includes(w.preview))w.preview=w.ids[0]||null;return '<div class="ew-workspace tw-workspace pw-workspace">'+twHeader()+'<nav class="pw-mobile-tabs" aria-label="费用核算工作区">'+B('计费合同','pw-panel',pwView.panel==='materials'?'active':'','data-panel="materials"')+B('费用设置','pw-panel',pwView.panel==='config'?'active':'','data-panel="config"')+'</nav><div class="pw-layout" data-pw-panel="'+pwView.panel+'">'+pwMaterials()+pwPanel()+'</div></div>';};
twMountPreview=function(){if(pwPreparing())return;return pwBase.twMountPreview();};
configurationFragment=function(id,c){if(id!=='prepaid')return pwBase.configurationFragment(id,c);return{exec_mode:'custom',custom_config:{parameter_settings:{exec_phase:'extract',expense_type:PW_TYPES[EXPENSE_TYPES.indexOf(c.feeType)]||'',expense_type_label:c.feeType,billing_agreement_prompt_id:c.stages.agreement.backendId||'',billing_agreement_prompt_content:c.stages.agreement.content||'',cost_calculation_prompt_id:c.stages.calculation.backendId||'',cost_calculation_prompt_content:c.stages.calculation.content||'',billing_base_wan:null},parameter_template:'',prompt_uuid:'prompt'}};};
makeResult=function(t){const rows=pwBase.makeResult(t);if(t.toolId!=='prepaid')return rows;t.billingByDoc=Object.fromEntries((t.successIds||[]).map(id=>[id,structuredClone(file(id)?.billing||null)]));return rows.map(r=>({...r,billing_snapshot:structuredClone(t.billingByDoc[r.doc]||null)}));};
function pwCurrentView(t){if(pwView.task!==t.id){Object.assign(pwView,{task:t.id,tab:t.status==='completed'?'report':'agreement',query:'',page:1});}return pwView;}
function pwFiltered(t){const q=pwView.query.trim().toLowerCase();return pwRows(t).filter(r=>pwReadable(r)&&[file(r.doc)?.name,r.clause].join(' ').toLowerCase().includes(q));}
function pwAgreementList(t){const rows=pwFiltered(t),pages=Math.max(1,Math.ceil(rows.length/pwView.size));pwView.page=Math.max(1,Math.min(pwView.page,pages));const shown=rows.slice((pwView.page-1)*pwView.size,pwView.page*pwView.size);return '<div class="pw-agreements-scroll">'+shown.map(r=>'<article class="pw-agreement"><div><h3>'+E(file(r.doc)?.name||'合同资料')+'</h3>'+A('查看原文','pw-source','data-index="'+r.index+'"')+'</div><p>'+E(r.clause||'本条未返回计费约定。')+'</p>'+(r.billing?'<small>'+E(r.billing.type)+' · '+(r.billing.rate?'按基数比例计费':r.billing.fixed!=null?'合同固定总价':'计费条件待核对')+'</small>':'<small>计费条件待核对</small>')+'</article>').join('')+(!shown.length?'<div class="pw-empty">没有匹配的计费约定。可调整查找条件或核对合同资料。</div>':'')+'</div><div class="pw-pager"><span>共 <strong>'+rows.length+'</strong> 份</span><div>'+B('上一页','pw-page','sm','data-step="-1" '+(pwView.page===1?'disabled':''))+'<span>第 '+pwView.page+' / '+pages+' 页</span>'+B('下一页','pw-page','sm','data-step="1" '+(pwView.page===pages?'disabled':''))+'</div></div>';}
function pwBaseForm(t){const editable=t.status==='awaiting'&&!t.calculating,n=pwRows(t).filter(r=>pwReadable(r)).length;return '<aside class="pw-base-form"><h3>确认计费基数</h3><p>核对合同约定后，填写本次费用计算使用的基数。</p><label for="fee-base">计费基数（元）<input id="fee-base" type="text" inputmode="decimal" data-pw-input="base" aria-label="计费基数，单位元" placeholder="例如：1,000,000.00" value="'+E(t.base??'')+'" '+(editable?'':'readonly')+'></label><small>'+(n>1?'本基数用于本次任务的全部 '+n+' 份合同；每份合同分别按其计费约定计算。':'按本份合同的计费约定计算，金额单位为元。')+'</small><p id="pw-base-error" class="error" role="alert"></p>'+B(t.calculating?'费用计算中…':t.status==='completed'?'费用报告已生成':'计算并生成报告','calculate-fee','primary w100',editable?'':'disabled')+'<p class="pw-base-note">'+(t.status==='completed'?'本次基数已保留。需要调整时，点击上方“再次分析”。':'计费约定已保存，可稍后从任务中心继续。')+'</p></aside>';}
function pwReport(t){const native=pwNativeReport(t);if(native)return '<article class="pw-report"><h2>费用计算报告</h2><div>'+previewMarkdown(native)+'</div></article>';const rows=pwRows(t).filter(r=>pwReadable(r)),calculated=rows.filter(r=>pwCalculation(t,r)?.status==='calculated');if(!calculated.length)return '<div class="pw-empty"><h3>费用报告尚未生成</h3><p>请先核对计费约定，再填写计费基数继续计算。</p>'+B('填写计费基数','pw-to-base','soft')+'</div>';const total=calculated.reduce((n,r)=>n+Number(pwCalculation(t,r).fee),0);return '<article class="pw-report"><div class="pw-report-title"><div><h2>费用计算报告</h2><p>'+E(t.config.feeType)+' · 计费基数 '+pwMoney(t.base)+' 元</p></div><div class="pw-total"><span>'+(calculated.length===rows.length?'计算费用合计':'已计算费用小计')+'（元）</span><strong>'+pwMoney(total)+'</strong></div></div><p class="pw-report-note">已计算 <strong>'+calculated.length+'</strong> 份'+(calculated.length<rows.length?'，另有 <strong>'+(rows.length-calculated.length)+'</strong> 份未计算':'')+'；请结合合同履约、结算凭证及审批资料核验。</p><div class="pw-calculation-table"><table><thead><tr><th>合同 / 计算依据</th><th>计算过程</th><th>费用（元）</th><th>核验</th></tr></thead><tbody>'+rows.map(r=>{const c=pwCalculation(t,r);return '<tr><td><b>'+E(file(r.doc)?.name)+'</b><small>'+E(r.clause)+'</small></td><td>'+E(c?.formula||c?.reason||'未返回可计算条件')+'</td><td>'+(c?.status==='calculated'?'<strong>'+pwMoney(c.fee)+'</strong>':'<span class="pw-uncomputed">未计算</span>')+'</td><td>'+A('查看原文','pw-source','data-index="'+r.index+'"')+'</td></tr>';}).join('')+'</tbody></table></div></article>';}
prepaidResults=function(t){pwCurrentView(t);const rows=pwRows(t).filter(r=>pwReadable(r));return '<section class="pw-results"><div class="pw-result-tabs" role="tablist" aria-label="费用核算结果">'+[['agreement','计费约定'],['report','费用报告']].map(([key,label])=>'<button role="tab" aria-selected="'+(pwView.tab===key)+'" data-action="pw-tab" data-tab="'+key+'" class="'+(pwView.tab===key?'active':'')+'">'+label+'</button>').join('')+(pwView.tab==='report'&&(t.fee!=null||pwNativeReport(t))?B('下载报告','pw-download-report','sm',trCanDownload(t)?'':'disabled'):'')+'</div>'+(pwView.tab==='agreement'?'<div class="pw-result-grid"><section class="pw-agreements"><div class="pw-agreement-toolbar"><span>已提取 <strong>'+rows.length+'</strong> 份合同</span><div class="search">'+I('search','icon-sm')+'<input data-pw-input="query" aria-label="查找计费约定" placeholder="查找合同或计费约定" value="'+E(pwView.query)+'"></div></div><div id="pw-agreement-list">'+pwAgreementList(t)+'</div></section>'+pwBaseForm(t)+'</div>':pwReport(t))+'</section>';};
function pwReportText(t){const rows=pwRows(t).filter(r=>pwReadable(r,true)),native=pwNativeReport(t,true);return '费用计算报告\n任务：'+t.name+'\n费用类型：'+t.config.feeType+'\n计费基数（元）：'+(t.base??'未填写')+'\n\n'+(native?native+'\n\n':'')+rows.map((r,i)=>{const c=pwCalculation(t,r);return(i+1)+'. '+(file(r.doc)?.name||'合同资料')+'\n计费约定：'+r.clause+'\n计算过程：'+(c?.formula||c?.reason||'尚未计算')+'\n费用（元）：'+(c?.status==='calculated'?pwMoney(c.fee):'未计算')+'\n来源：'+r.refs.map(id=>file(id)?.name).join('；');}).join('\n\n')+'\n\n请结合合同履约、结算凭证及审批资料核验。';}
reportText=function(t,title){return t.toolId==='prepaid'?pwReportText(t):pwBase.reportText(t,title);};
exportRows=function(t,scope='all'){if(t.toolId!=='prepaid')return pwBase.exportRows(t,scope);const rows=pwRows(t).filter(r=>pwReadable(r,true)&&(scope==='all'||r.doc===scope));return[['来源合同','费用类型','计费约定','计费基数（元）','计算过程','计算费用（元）','计算状态'],...rows.map(r=>{const c=pwCalculation(t,r);return[file(r.doc)?.name,t.config.feeType,r.clause,t.base??'',c?.formula||c?.reason||'',c?.status==='calculated'?c.fee:'',c?.status==='calculated'?'已计算':'未计算'];})];};
doExport=function(){const t=currentTask();if(t?.toolId!=='prepaid'||$('#export-format')?.value!=='json')return pwBase.doExport();if(!trCanDownload(t))return toast('当前结果没有下载权限。');const scope=$('#export-scope')?.value||'all',rows=pwRows(t).filter(r=>pwReadable(r,true)&&(scope==='all'||r.doc===scope));if(!rows.length)return toast('当前范围没有可导出的结果。');const ids=new Set(rows.map(r=>r.doc));download((t.name||'待摊费用')+'-结果.json',JSON.stringify({task:t.name,config:t.config,execution_config:t.configFragment,continuation:t.prepaidContinuation||null,billing_base_yuan:t.base??null,results:rows.flatMap(r=>r.raws||[r.raw]),calculations:(t.prepaidCalculations||[]).filter(r=>ids.has(r.doc))},null,2),'application/json;charset=utf-8');closeModal();};
tcOutput=function(t){if(t.toolId!=='prepaid')return pwBase.tcOutput(t);if(t.calculating)return{text:'费用计算中',hint:'计费约定和基数已保留，完成后查看费用报告'};if(t.status!=='completed')return pwBase.tcOutput(t);if(pwNativeReport(t))return{text:'费用报告已生成',hint:'核对计算依据、过程和合同来源'};if(!t.prepaidCalculations)return pwBase.tcOutput(t);const rows=pwRows(t).filter(r=>pwReadable(r)),done=rows.filter(r=>pwCalculation(t,r)?.status==='calculated').length,left=rows.length-done;return{text:'已完成 '+done+' 份费用测算'+(left?' · '+left+' 份未计算':''),hint:'各合同分别列出计费约定、计算过程及原文来源'};};
trDownloadPage=function(t){const html=pwBase.trDownloadPage(t);if(t.toolId!=='prepaid')return html;const root=document.createElement('div');root.innerHTML=html;const card=root.querySelector('[data-kind="fee"]')?.closest('article');if(card){card.querySelector('small').textContent='Word / TXT';card.querySelector('p').textContent='各合同计费约定、基数、计算过程、费用与原文来源。';if(pwNativeReport(t))card.querySelector('button').disabled=!trCanDownload(t);}return root.innerHTML;};
modalContent=function(){if(!pwActive())return pwBase.modalContent();if(modal==='pw-sources'){const r=pwRows(currentTask()).find(r=>r.index===modalData.index);if(!r||!pwReadable(r))return modalFrame('无法核对来源','','来源资料已变化，请关闭后重试。',B('关闭','close-modal'),'medium');return modalFrame('核对计费依据',file(r.doc)?.name||'合同资料','<p class="pw-source-clause">'+E(r.clause)+'</p><div class="pw-source-list">'+r.refs.map(id=>auditFileAccess(file(id)).preview?B(E(file(id)?.name),'source','sm','data-id="'+E(id)+'"'):'<p>'+E(file(id)?.name)+'（无预览权限）</p>').join('')+'</div>',B('关闭','close-modal'),'medium');}if(modal==='pw-download-report')return modalFrame('下载费用报告','保留合同约定、计算过程及原文来源。','<p>任务：'+E(currentTask()?.name)+'</p>',B('取消','close-modal')+B('下载文本','download-fee')+B('下载 Word','pw-download-word','primary'),'small');return pwBase.modalContent();};
closeModal=function(){if(pwActive()&&modal==='source'&&pwSourceReturn){const back=pwSourceReturn;pwSourceReturn=null;pwBase.closeModal();openModal('pw-sources',back);return;}return pwBase.closeModal();};
function pwContinue(t){if(t.status!=='awaiting'||t.calculating)return;const num=pwParseBase(t.base);if(!Number.isFinite(num)){const error=$('#pw-base-error');if(error)error.textContent='请输入大于0且不超过10万亿元的金额，最多保留两位小数。';$('#fee-base')?.focus();return;}const rows=pwRows(t).filter(r=>pwReadable(r));if(!rows.length)return toast('没有可继续计算的计费约定，请核对来源资料。');const calculations=rows.map(r=>{const b=r.billing;if(!b||b.type!==t.config.feeType)return{doc:r.doc,status:'uncomputed',reason:!b?'未提取到完整计费条件':'合同费用类型与本次选择不一致'};const rate=Number(b.rate),fixed=Number(b.fixed);if(!((Number.isFinite(rate)&&rate>0)||(b.fixed!=null&&Number.isFinite(fixed)&&fixed>=0)))return{doc:r.doc,status:'uncomputed',reason:'未提取到有效费率或合同固定总价'};return{doc:r.doc,status:'calculated',formula:pwFormula(b,num),fee:Math.round((rate>0?num*rate:fixed)*100)/100};});if(!calculations.some(r=>r.status==='calculated')){const error=$('#pw-base-error');if(error)error.textContent='尚未取得可计算的计费条件，请核对合同约定，调整提取要求后再分析。';return;}t.base=String(num);t.prepaidContinuation={task_uuid:t.id,billing_base_wan:num};t.calculating=true;persist();render();setTimeout(()=>{t.prepaidCalculations=calculations;t.fee=Math.round(calculations.filter(r=>r.status==='calculated').reduce((n,r)=>n+r.fee,0)*100)/100;t.calculating=false;t.status='completed';t.phase='费用计算报告已生成';t.completed=new Date().toISOString();t.lastProgressAt=t.completed;persist();if(currentTask()?.id===t.id){pwView.tab='report';render();}toast('费用报告已生成，计费约定和基数已保留。');},650);}
handleAction=function(action,el){if(!pwActive())return pwBase.handleAction(action,el);const d=el?.dataset||{},t=currentTask();if(action==='pw-panel'){pwView.panel=d.panel;render();return;}if(action==='pw-tab'){pwView.tab=d.tab;render();return;}if(action==='pw-page'){pwView.page+=Number(d.step);$('#pw-agreement-list').innerHTML=pwAgreementList(t);return;}if(action==='pw-to-base'){pwView.tab='agreement';render();$('#fee-base')?.focus();return;}if(action==='calculate-fee'&&t)return pwContinue(t);if(action==='pw-source'){const r=pwRows(t).find(r=>r.index===Number(d.index));if(!r||!pwReadable(r))return toast('来源资料已变化，暂时无法核验。');const id=r.refs.find(id=>auditFileAccess(file(id)).preview);if(!id)return toast('当前没有原文预览权限。');if(r.refs.length>1)return openModal('pw-sources',{index:r.index});return pwBase.handleAction('source',{dataset:{id}});}if(['pw-download-report','download-fee','pw-download-word'].includes(action)){if(!t||!trCanDownload(t))return toast('当前结果没有下载权限。');if(t.fee==null&&!pwNativeReport(t))return toast('费用报告尚未生成。');if(action==='pw-download-report')return openModal('pw-download-report');const name=(t.name||'待摊费用')+'-费用计算报告';if(action==='pw-download-word')download(name+'.docx',v6Docx(pwReportText(t).split('\n')),'application/vnd.openxmlformats-officedocument.wordprocessingml.document');else download(name+'.txt',pwReportText(t),'text/plain;charset=utf-8');if(modal==='pw-download-report')closeModal();return;}if(action==='source'&&modal==='pw-sources')pwSourceReturn=structuredClone(modalData);if(action==='tr-artifact'&&d.kind==='fee'&&t)return handleAction('pw-download-report',el);if(pwPreparing()&&['tw-preview','preview'].includes(action)){ws().preview=d.id;return pwBase.handleAction('source',el);}if(pwPreparing()&&action==='tw-panel'){pwView.panel=d.panel==='materials'?'materials':'config';render();return;}return pwBase.handleAction(action,el);};
window.addEventListener('input',e=>{if(!pwActive())return;const key=e.target.dataset.pwInput;if(!key)return;e.stopImmediatePropagation();if(key==='base'){const t=currentTask();if(t?.status==='awaiting'&&!t.calculating){t.base=e.target.value;const error=$('#pw-base-error');if(error)error.textContent='';persist();}}if(key==='query'){pwView.query=e.target.value;pwView.page=1;$('#pw-agreement-list').innerHTML=pwAgreementList(currentTask());}},true);
render();
